% make_figures: figures are regenerated only from saved results;
% no simulation is run. Legend/axis use omega_c and r=omega_o/omega_c
% (TeX interpreter). Output: P.figures (PDF) and P.results (PNG).
function make_figures()
P=sim_config();set(groot,'defaultFigureVisible','off');if ~isfolder(P.figures),mkdir(P.figures);end;U=readtable(fullfile(P.results,'summary.csv'),'TextType','string');B=load(fullfile(P.results,'design_gains.mat'));R=readtable(fullfile(P.results,'sensitivity_ratio.csv'));Q=readtable(fullfile(P.results,'sensitivity_mismatch.csv'),'TextType','string');
f=figure('Position',[100 100 850 330]);tiledlayout(1,2,'TileSpacing','compact');colors=lines(3);
nexttile;hold on;leg={};for j=1:3,wc=[3 6 10];for kind=[4 7],a=R(R.WC==wc(j)&R.Kind==kind,:);v=a.Ms;v(~isfinite(v))=NaN;style='--';label='commanded';if kind==7,style='-';label='actuator-aware';end;semilogy(a.Ratio,v,style,'Color',colors(j,:),'LineWidth',1.1);leg{end+1}=sprintf('%s, \\omega_c=%g',label,wc(j));end,end;set(gca,'YScale','log');yline(2,':k');xlabel('Bandwidth ratio r=\omega_o/\omega_c');ylabel('Refined input-sensitivity peak');grid on;legend(leg,'Location','northwest','FontSize',8,'Interpreter','tex');nexttile;hold on;for j=1:3,wc=[3 6 10];for kind=[4 7],a=R(R.WC==wc(j)&R.Kind==kind,:);style='--';if kind==7,style='-';end;plot(a.Ratio,a.Rho,style,'Color',colors(j,:));end,end;yline(1,':k');xlabel('Bandwidth ratio r=\omega_o/\omega_c');ylabel('Spectral radius');grid on;export('fig_sensitivity_ratio');
f=figure('Position',[100 100 800 340]);tiledlayout(1,2,'TileSpacing','compact');families={'PID','AA-Budget','AA-HalfGain'};colors=lines(3);
for panel=1:2,nexttile;hold on;for j=1:3,mu=[];ci=[];xx=[];for gamma=[.5 .75 1 1.25 1.5],cc=B.Curve(find(strcmp({B.Curve.Family},families{j})&[B.Curve.Gamma]==gamma,1)).Controller;a=U(U.Experiment=="E4"&U.Ctrl==string(cc.name)&abs(U.Gamma-gamma)<1e-10,:);mu(end+1)=a.RMSE_mean_mm;ci(end+1)=a.RMSE_ci95_mm;if panel==1,xx(end+1)=gamma;else,xx(end+1)=a.Increment;end;end;errorbar(xx,mu,ci,'-o','Color',colors(j,:),'LineWidth',1,'MarkerSize',4);end;ylabel('Position RMSE [mm]');grid on;if panel==1,xlabel('Local increment-ceiling multiplier \gamma (cascade ceiling fixed)');else,xlabel('RMS rotor-command increment [rad/s]');end;legend(families,'Location','northeast','FontSize',8);end;export('fig_budget_performance');
f=figure('Position',[100 100 800 330]);tiledlayout(1,2,'TileSpacing','compact');names={'PID-Budget','AA-Budget','AA-HalfGain'};for panel=1:2,nexttile;hold on;for c=1:3,for h=[1 3],axis='lag';if panel==2,axis='delay';end;a=Q(Q.Ctrl==string(names{c})&Q.Class==h&Q.Axis==string(axis),:);v=a.Ms;v(~isfinite(v))=NaN;style='-';if h==3,style='--';end;semilogy(a.Value,v,style,'LineWidth',1.1);end,end;set(gca,'YScale','log');yline(2,':k');ylabel('Refined sensitivity peak');grid on;if panel==1,xlim([10 150]);xline(30,':k');xlabel('True rotor time constant [ms]');else,xlim([0 30]);xline(5,':k');xlabel('True measurement delay [ms]');end;legend({'PID-Budget xy','PID-Budget roll/pitch','AA-Budget xy','AA-Budget roll/pitch','AA-HalfGain xy','AA-HalfGain roll/pitch'},'Location','northwest','FontSize',7);end;export('fig_sensitivity_mismatch');
f=figure('Position',[100 100 980 290]);tiledlayout(1,3,'TileSpacing','compact');for c=1:3,nexttile;X=nan(8,3);for it=1:8,for id=1:3,a=U(U.Experiment=="E7"&U.Ctrl==string(names{c})&U.Tau_ms==P.taus(it)*1000&U.Delay_ms==P.delays(id),:);X(it,id)=a.Failures+a.ThresholdExceedances;end,end;imagesc(P.delays,P.taus*1000,X);set(gca,'YDir','normal');setclim([0 10]);colorbar;xlabel('True measurement delay [ms]');ylabel('Rotor time constant [ms]');title(names{c});end;export('fig_mismatch_counts');
f=figure('Position',[100 100 820 340]);tiledlayout(1,2,'TileSpacing','compact');colors=lines(4);for panel=1:2,nexttile;hold on;for c=1:4,a=U(U.Experiment=="E1"&U.Ctrl==string(B.C(c).name),:);if panel==1,errorbar(c,a.RMSE_mean_mm,a.RMSE_ci95_mm,'o','Color',colors(c,:),'MarkerFaceColor',colors(c,:));else,plot(c,a.Increment,'o','Color',colors(c,:),'MarkerFaceColor',colors(c,:));end,end;set(gca,'XTick',1:4,'XTickLabel',{B.C(1:4).name},'XTickLabelRotation',20);grid on;if panel==1,set(gca,'YScale','log');ylabel('Position RMSE [mm], 95% CI');else,ylabel('RMS rotor-command increment [rad/s]');end;end;export('fig_nominal');
f=figure('Position',[100 100 820 330]);tiledlayout(1,2,'TileSpacing','compact');for panel=1:2,nexttile;hold on;for c=[1 2 4],a=U(ismember(U.Experiment,["E5-1","E5-2","E5-3","E5-4"])&U.Ctrl==string(B.C(c).name),:);[xx,ii]=sort(a.NoiseScale);if panel==1,yy=a.RMSE_mean_mm(ii);else,yy=a.Increment(ii);end;plot(xx,yy,'-o','DisplayName',B.C(c).name);end;grid on;xlabel('White sensor-noise standard-deviation multiplier');if panel==1,ylabel('Mean position RMSE [mm]');else,ylabel('Rotor-command increment [rad/s]');end;legend('Location','northwest');end;export('fig_noise_activity');
f=figure('Position',[100 100 800 330]);D=load(fullfile(P.results,'nominal_waveform.mat'));L=D.a;tiledlayout(1,2,'TileSpacing','compact');nexttile;plot(L.t,1000*(L.r(:,1:3)-L.x(:,1:3)));grid on;xlim([0 40]);xlabel('Time [s]');ylabel('AA-Budget position errors [mm]');legend({'x','y','z'});nexttile;plot(L.t,L.wcmd(:,1));hold on;plot(L.t,L.x(:,13));xlim([10 12]);grid on;xlabel('Time [s]');ylabel('Rotor 1 speed [rad/s]');legend({'command','actual'});export('fig_nominal_waveform');fprintf('FIGURES_PASS\n');
 function setclim(v),if exist('clim','file'),clim(v);else,caxis(v);end,end
 function export(name),exportgraphics(f,fullfile(P.figures,[name '.pdf']),'ContentType','vector');exportgraphics(f,fullfile(P.results,[name '.png']),'Resolution',180);close(f);end
end
